
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_k_absp3_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_k_absp3", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-2.240391992996843e+01, -2.058004662161541e+01, -1.809160065391173e+01, -1.477384433486907e+01, -1.049427451390265e+01, -5.229741651403899e+00, 8.178507547297998e-01, 7.089174027252761e+00, 1.252493342831513e+01, 1.502584388187564e+01, 9.474159683903382e+00, -1.532567987483412e-01, -6.512780018181510e-01, -2.435844034994734e-02, 4.551867216396862e-01, 6.606521439503027e-01, 6.875551214479435e-01, 6.461118911273405e-01, 6.033989613900942e-01, 5.743479424022315e-01]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


